def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Fill between diagonal sides that converge to or diverge from a shared apex.
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v != 0]
        for i, left in enumerate(cols):
            for right in cols[i + 1:]:
                span = right - left
                if span < 2 or span % 2:
                    continue
                radius = span // 2
                # Check that the sides continue diagonally toward a common apex.
                apex_r = r - radius
                if apex_r >= 0 and grid[apex_r][left + radius] != 0:
                    continue
                # At the current row, fill only intervals supported by the
                # diagonal boundary points on the rows immediately above/below.
                if r > 0 and grid[r - 1][left + 1] != 0 and grid[r - 1][right - 1] != 0:
                    for c in range(left + 1, right):
                        if grid[r][c] == 0:
                            out[r][c] = 2
                    break
    return out
